function createSpatialGrid(entities,cellSize=140){const cells=new Map();for(const entity of entities){const radius=entity.r||0,minX=Math.floor((entity.x-radius)/cellSize),maxX=Math.floor((entity.x+radius)/cellSize),minY=Math.floor((entity.y-radius)/cellSize),maxY=Math.floor((entity.y+radius)/cellSize);for(let x=minX;x<=maxX;x++)for(let y=minY;y<=maxY;y++){const key=`${x},${y}`,cell=cells.get(key)||[];cell.push(entity);cells.set(key,cell)}}return{cells,cellSize}}
