function newStats(character){const base=DATA.characters[character];return{damage:base.damage,fireRate:base.fireRate,speed:base.speed,maxHp:base.hp,projectileSpeed:base.projectileSpeed,projectileSize:character==='druid'?10:4,projectileLife:character==='druid'?2.1:1.3,projectiles:1,pierce:0,critChance:.1,critDamage:1.8,lifesteal:0,thorns:0,magnet:MECHANICS.magnetRadius({}),powder:0,totem:0,vault:0,cooldowns:{qReadyAt:0,eReadyAt:0,rReadyAt:0}}}
