  if(msg.type==='joinLobby'){if(lobby?.game)return this.emit(client,'joinError',{message:'Nie można opuścić aktywnego meczu.'});const target=this.lobbies.get(msg.code);if(!target||target.game||target.players.length>=MAX_PLAYERS)return this.emit(client,'joinError',{message:target?.players.length>=MAX_PLAYERS?'Lobby jest pełne.':'Nie znaleziono dostępnego lobby.'});this.leave(client,true);target.players.push({id:client.playerId,accountUserId:client.accountUserId,name:`Gracz ${target.players.length+1}`,host:false,ready:false,character:'scout',connected:true,choiceRound:0});client.lobby=target.code;return this.publish(target)}
  if(msg.type==='leaveLobby'&&lobby){if(lobby.game&&!lobby.game.ended){const departing=lobby.game.players[client.playerId];if(departing){departing.leaveAtGameTime=lobby.game.time;departing.settlementSnapshot={coins:departing.coins||0,kills:departing.kills||0,time:lobby.game.time||0,character:departing.character};departing.alive=false;departing.hp=0;departing.input={}}lobby.players=lobby.players.filter(player=>player.id!==client.playerId);client.lobby='';this.emit(client,'leftLobby');if(!this.endIfDefeated(lobby)){this.resumeUpgradeIfReady(lobby);this.updateManualPause(lobby);this.syncNetworkPause(lobby)}if(lobby.players.length){this.migrate(lobby);this.publish(lobby)}else{this.clearFlowFields(lobby.game.matchId);this.lobbies.delete(lobby.code)}return}this.leave(client,true);return this.emit(client,'leftLobby')}
